  "atomic_questions": [
    "What is the objective of this production plan — are we maximizing total profit (unit price minus raw material cost, minus the operating costs of the equipment used), or is the objective something else such as maximizing total revenue or minimizing total cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

